set -euo pipefail
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
BACKUP=/opt/minecraft/server/backups/fresh-world-$STAMP
install -d -m 0755 "$BACKUP"
systemctl stop minecraft.service
cp -a /opt/minecraft/server/server.properties "$BACKUP/server.properties.before-fresh-world"
mv /opt/minecraft/server/world "$BACKUP/world"
if [ -f /opt/minecraft/server/config/brigada-core/state.json ]; then
  mv /opt/minecraft/server/config/brigada-core/state.json "$BACKUP/world-core-state.json"
fi
cp -a /opt/minecraft/server/mods/brigada-core-0.1.0.jar "$BACKUP/previous-world-core.jar"
install -m 0644 /opt/brigada-core-src/build/libs/brigada-core-0.1.0.jar /opt/minecraft/server/mods/brigada-core-0.1.0.jar
install -d -m 0755 /opt/minecraft/resourcepack
if [ -f /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip ]; then
  mv /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip "$BACKUP/previous-ui-pack.zip"
fi
printf '%s' '' | base64 -d > /opt/minecraft/resourcepack/world-ui-26.3-snapshot-9.zip
chmod 0644 /opt/minecraft/resourcepack/world-ui-26.3-snapshot-9.zip
PROP=/opt/minecraft/server/server.properties
sed -i '/^resource-pack=/d;/^resource-pack-sha1=/d;/^resource-pack-id=/d;/^resource-pack-prompt=/d;/^require-resource-pack=/d;/^level-seed=/d' "$PROP"
printf '%s\n' 'level-seed=' 'resource-pack=http://143.246.197.187:8088/world-ui-26.3-snapshot-9.zip' 'resource-pack-sha1=aaf35e9b54f624f8373d0e407cbe9739d982e85a' 'resource-pack-id=73e66563-b99b-4a91-9152-655b7dc02498' 'resource-pack-prompt={"text":"Скачать оформление сервера?","color":"gold","bold":true}' 'require-resource-pack=false' >> "$PROP"
systemctl start minecraft.service
sleep 90
printf 'SERVICES\n'
systemctl is-active minecraft.service
systemctl is-active brigada-pack.service
printf '\nPORTS\n'
ss -ltnp | grep -E ':25565|:8088' || true
printf '\nNEW_WORLD\n'
du -sh /opt/minecraft/server/world
find /opt/minecraft/server/world -maxdepth 1 -type f -printf '%f %TY-%Tm-%TdT%TH:%TM:%TS\n' | sort | head -n 20
printf '\nBACKUP\n%s\n' "$BACKUP"
du -sh "$BACKUP/world"
printf '\nPACK\n'
sha1sum /opt/minecraft/resourcepack/world-ui-26.3-snapshot-9.zip
curl -fsSI http://143.246.197.187:8088/world-ui-26.3-snapshot-9.zip | head -n 5
printf '\nMOD\n'
sha256sum /opt/minecraft/server/mods/brigada-core-0.1.0.jar
printf '\nPROPERTIES\n'
grep -E '^(level-name|level-seed|resource-pack|require-resource-pack)' "$PROP"
printf '\nLOG\n'
journalctl -u minecraft.service -n 220 --no-pager | grep -E 'World Core|Loaded 120|Preparing|Done|ERROR|Exception|Failed|dialog' | tail -n 120 || true
